            applicationThread = Thread.currentThread();
            applicationThreadStarted.countDown();

            try {
                if (args.length == 0) {
                    System.out.println("ERROR 0 missing-script");
                    return;
                }
                processScript(Path.of(args[0]));
            } finally {
                System.out.flush();
                Gdx.app.exit();
